// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor1, address actor2) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(amount1 > 0 && amount1 < 1 ether);
        vm.assume(amount2 > 0 && amount2 < 1 ether);
        vm.assume(actor1 != address(0) && actor1 != address(c));
        vm.assume(actor2 != address(0) && actor2 != address(c) && actor2 != actor1);

        vm.deal(actor1, amount1);
        vm.prank(actor1);
        (bool ok1, ) = address(c).call{value: amount1}("");
        assertTrue(ok1);

        vm.deal(actor2, amount2);
        vm.prank(actor2);
        (bool ok2, ) = address(c).call{value: amount2}("");
        assertTrue(ok2);

        // General rule: each successful deposit increments depositsCount by exactly 1,
        // so two successful deposits always leave depositsCount == 2.
        assertEq(c.depositsCount(), 2);
    }
}
